# Executed in the real notification QA cluster, after all baseline checks.
normal_validity=sql("SELECT coalesce(jsonb_object_agg(d.id,push_delivery_valid_v1(d.id)),'{}') FROM notification_push_deliveries d;")
production=json.loads((ROOT/'outputs/admin-push-self-test/db-predecessors.json').read_text())
for function in production['functions']:sql(function['definition']+';')
constraint=next(x for x in production['constraints'] if x['name']=='notifications_deep_link_type_check')['definition']
sql('ALTER TABLE notifications DROP CONSTRAINT notifications_deep_link_type_check; ALTER TABLE notifications ADD CONSTRAINT notifications_deep_link_type_check '+constraint+';')
sql((ROOT/'supabase/migrations/202611020001_admin_push_self_test_v1.sql').read_text())
check('self-test installation keeps reminder OFF',sql('SELECT NOT enabled FROM notification_schedule_reminder_config;')=='t')
def as_user(user,query,fail=False):return sql(f"SET request.jwt.claim.sub='{uid(user)}'; SET ROLE authenticated; "+query,fail=fail)
for user in [8001,8002,8003,8004]:
 sql(f"INSERT INTO profiles VALUES('{uid(user)}','Synthetic self test {user}',true,'active','{'staff' if user==8002 else 'admin'}'); INSERT INTO operation_memberships VALUES('{uid(user)}','{'staff' if user==8002 else 'owner'}',true);")
 sql(f"INSERT INTO push_subscriptions(profile_id,endpoint,p256dh,auth) VALUES('{uid(user)}','https://web.push.apple.com/synthetic-{user}','SYNTHETIC','SYNTHETIC');")
def subscription(user):return json.loads(sql(f"SELECT json_build_object('id',id,'binding_id',binding_id) FROM push_subscriptions WHERE profile_id='{uid(user)}' AND revoked_at IS NULL LIMIT 1;"))
def send(user,req,sub=None,fail=False):
 s=sub or subscription(user)
 return as_user(user,f"SELECT send_admin_push_self_test_v1('{uid(req)}','{s['id']}','{s['binding_id']}');",fail)
check('non-admin hidden',json.loads(as_user(8002,'SELECT get_admin_push_self_test_v1();'))['allowed']==False)
check('non-admin write denied','SELF_TEST_FORBIDDEN' in send(8002,9001,fail=True))
check('anonymous write ACL denied','permission denied' in sql(f"SELECT send_admin_push_self_test_v1('{uid(9001)}','{uid(1)}','{uid(2)}');",'anon',True))
check('cannot target another user subscription','SUBSCRIPTION_CHANGED' in send(8001,9001,subscription(8003),True))
check('client cannot supply title body URL','does not exist' in as_user(8001,"SELECT send_admin_push_self_test_v1(p_title=>'x');",True))
sql(f"INSERT INTO push_subscriptions(profile_id,endpoint,p256dh,auth) VALUES('{uid(8001)}','https://web.push.apple.com/ambiguous','SYNTHETIC','SYNTHETIC');")
check('multiple active devices fail closed','blocked' in json.loads(as_user(8001,'SELECT get_admin_push_self_test_v1();')) and 'SUBSCRIPTION_CHANGED' in send(8001,9001,fail=True))
sql("UPDATE push_subscriptions SET revoked_at=now() WHERE endpoint='https://web.push.apple.com/ambiguous';")
context=json.loads(as_user(8001,'SELECT get_admin_push_self_test_v1();'))
check('only safe device metadata exposed',set(context['subscription'])=={'id','binding_id','last_seen_at','provider'})
result=json.loads(send(8001,9001)); nid=result['notification_id'];did=result['delivery_id']
check('admin request creates exactly one notification and delivery',sql(f"SELECT count(*) FROM notification_push_deliveries WHERE notification_id='{nid}';")=='1')
check('self recipient fixed and no announcement',sql(f"SELECT recipient_id='{uid(8001)}' AND announcement_id IS NULL AND deep_link_type='CENTER' FROM notifications WHERE id='{nid}';")=='t')
check('fixed DB copy',sql(f"SELECT title||'|'||message FROM notifications WHERE id='{nid}';")=='[테스트 알림] 새 미리보기 확인|P&M OS 알림 표시 테스트입니다. 실제 업무 처리는 필요하지 않습니다.')
check('same request idempotent',json.loads(send(8001,9001))['notification_id']==nid)
check('fresh request rate limited','SELF_TEST_RATE_LIMIT' in send(8001,9002,fail=True))
check('private audit no client DML','permission denied' in as_user(8001,'UPDATE notification_push_self_test_audit SET action=action;',True))
check('self test visible in existing inbox without ACK',any(x['id']==nid and x['ack_required']==False for x in json.loads(as_user(8001,'SELECT get_notification_inbox_v1();'))['items']))
check('self test uses existing push validity',sql(f"SELECT push_delivery_valid_v1('{did}');")=='t')
sql(f"UPDATE profiles SET role='staff' WHERE id='{uid(8001)}';")
check('admin revocation before send invalidates delivery',sql(f"SELECT NOT push_delivery_valid_v1('{did}');")=='t')
sql(f"UPDATE profiles SET role='admin' WHERE id='{uid(8001)}';")
tok=uid(99991)
sql(f"UPDATE notification_push_deliveries SET status='PROCESSING',attempt_count=1,claim_token='{tok}',lease_until=now()+interval '1 minute' WHERE id='{did}';")
payload=json.loads(sql(f"SET ROLE service_role; SELECT get_notification_push_delivery_v1('{did}','{tok}');"))
check('real leased delivery has self-test event',payload['category']=='PUSH_SELF_TEST' and payload['event_type']=='ADMIN_PUSH_SELF_TEST')
sql(f"SET ROLE service_role; SELECT finish_notification_push_delivery_v1('{did}','{tok}','RETRY',30);")
check('existing retry and failure audit preserved',sql(f"SELECT status='FAILED' AND last_error='RETRY' FROM notification_push_deliveries WHERE id='{did}';")=='t' and sql("SELECT count(*) FROM notification_push_self_test_audit WHERE action='FAILED';")=='1')
sql(f"UPDATE notification_push_deliveries SET status='PROCESSING',attempt_count=2,claim_token='{tok}',lease_until=now()+interval '1 minute' WHERE id='{did}';")
sql(f"SET ROLE service_role; SELECT finish_notification_push_delivery_v1('{did}','{tok}','SENT');")
check('SENT audit and requesting actor preserved',sql(f"SELECT count(*) FROM notification_push_self_test_audit WHERE action='SENT' AND actor_id='{uid(8001)}';")=='1')
check('only one delivery after retry and idempotency',sql(f"SELECT count(*) FROM notification_push_deliveries WHERE notification_id='{nid}';")=='1')
# Two clients repeating the same request concurrently serialize to one row.
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as pool: values=list(pool.map(lambda _:send(8003,9003),range(2)))
check('concurrent same request exactly once',len(set(json.loads(v)['notification_id'] for v in values))==1)
# Explicit abort must roll back event/notification/delivery/audit atomically.
s=subscription(8004)
rollback=as_user(8004,f"BEGIN; SELECT send_admin_push_self_test_v1('{uid(9004)}','{s['id']}','{s['binding_id']}'); ROLLBACK;")
check('whole request transaction rollback',sql(f"SELECT count(*) FROM notification_push_self_tests WHERE actor_id='{uid(8004)}';")=='0')
# Inject a failing delivery insert only in the isolated test cluster.
sql("CREATE FUNCTION qa_self_test_abort() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'QA_ABORT_DELIVERY'; END $$; CREATE TRIGGER qa_self_test_abort BEFORE INSERT ON notification_push_deliveries FOR EACH ROW EXECUTE FUNCTION qa_self_test_abort();")
check('delivery insertion failure rejects whole operation','QA_ABORT_DELIVERY' in send(8004,9020,fail=True))
check('failure leaves no test event notification or audit',sql(f"SELECT count(*) FROM notification_push_self_tests WHERE actor_id='{uid(8004)}';")=='0' and sql(f"SELECT count(*) FROM notification_events WHERE payload->>'actor_id'='{uid(8004)}';")=='0')
sql('DROP TRIGGER qa_self_test_abort ON notification_push_deliveries; DROP FUNCTION qa_self_test_abort();')
# Force cooldown expiration in disposable fixtures, not production logic.
sql(f"UPDATE notification_push_self_tests SET created_at=statement_timestamp()-interval '6 minutes' WHERE actor_id='{uid(8001)}';")
send(8001,9011)
sql(f"UPDATE notification_push_self_tests SET created_at=statement_timestamp()-interval '6 minutes' WHERE actor_id='{uid(8001)}';")
send(8001,9012)
sql(f"UPDATE notification_push_self_tests SET created_at=statement_timestamp()-interval '6 minutes' WHERE actor_id='{uid(8001)}';")
check('daily maximum three enforced','SELF_TEST_RATE_LIMIT' in send(8001,9013,fail=True))
sql(f"UPDATE push_subscriptions SET revoked_at=now() WHERE profile_id='{uid(8004)}';")
check('revoked subscription blocked','blocked' in json.loads(as_user(8004,'SELECT get_admin_push_self_test_v1();')))
check('original delivery validity unchanged',normal_validity==sql("SELECT coalesce(jsonb_object_agg(d.id,push_delivery_valid_v1(d.id)),'{}') FROM notification_push_deliveries d JOIN notifications n ON n.id=d.notification_id WHERE n.category<>'PUSH_SELF_TEST';"))
check('reminder remains OFF after self tests',sql('SELECT NOT enabled FROM notification_schedule_reminder_config;')=='t')
